#include <bits/stdc++.h>
using namespace std;

int main(void) {
	int n;
	long long k;
	long long A[200010];
	long long S[200010];
	int pre[200010];
	int s, t, p, b;
	long long a, X;
	long long ans;

	cin >> n >> k;
	for (int i = 0; i < n; i++)cin >> A[i];

	for (int i = 0; i < n; i++)pre[i] = -1;
	S[0] = 0;
	pre[0] = 0;

	for (int i = 0; i < n; i++) {
		S[i + 1] = S[i] + A[S[i] % n];
		if (pre[S[i + 1] % n] != -1) {
			s = pre[S[i + 1] % n];
			t = i + 1;
			break;
		}
		pre[S[i + 1] % n] = i + 1;
	}

	if (k <= s)ans = S[k];
	else {
		p = t - s;
		X = S[t] - S[s];
		a = (k - s - 1) / p;
		b = (k - s - 1) % p;
		ans = S[s + b + 1] + (a*X);
	}

	cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(void) {
	int n;
	long long k;
	long long a[200010];
	long long dp[40][200010];
	long long ans;

	cin >> n >> k;
	for (int i = 0; i < n; i++)cin >> a[i];

	for (int j = 0; j < n; j++)dp[0][j] = a[j];
	for (int i = 0; i < 39; i++) {
		for (int j = 0; j < n; j++) {
			dp[i + 1][j] = dp[i][j] + dp[i][(j+dp[i][j]) % n];
		}
	}

	ans = 0;
	for (int i = 0; i < 40; i++) {
		if (k & 1) {
			ans += dp[i][ans%n];
		}
		k = (k >> 1);
	}

	cout << ans << endl;
	return 0;
}

#include <iostream>
using namespace std;

// 入力で与えられる変数
long long N, K;
long long A[200009];

// その他の変数
long long LastTime[200009];
long long LastCand[200009];

int main() {
	// 入力
	cin >> N >> K;
	for (int i = 0; i < N; i++) cin >> A[i];

	// 配列の初期化
	// CurrentTime は現在の操作回数
	// CurrentCand は現在のアメの数
	long long CurrentTime = 0;
	long long CurrentCand = 0;
	for (int i = 0; i < N; i++) LastTime[i] = -1;
	for (int i = 0; i < N; i++) LastCand[i] = -1;

	// 手順 1: (u1, u2) を求める
	// CycleCand は 1 周期ごとに追加されるアメの数
	long long u1 = 0, u2 = 0;
	long long CycleCand = 0;
	while (true) {
		// 周期性が見つかる前に K 回目になってしまった
		if (CurrentTime == K) {
			cout << CurrentCand << endl;
			return 0;
		}
		// 周期性が見つかった
		if (LastTime[CurrentCand % N] != -1) {
			u1 = LastTime[CurrentCand % N];
			u2 = CurrentTime;
			CycleCand = CurrentCand - LastCand[CurrentCand % N];
			break;
		}
		// シミュレーション
		LastTime[CurrentCand % N] = CurrentTime;
		LastCand[CurrentCand % N] = CurrentCand;
		CurrentTime += 1;
		CurrentCand += A[CurrentCand % N];
	}

	// 手順 2: ギリギリまでを高速に求める
	// MaximumCycles は最大何周期分まで追加して良いか
	// FinalTime はギリギリまで考えたときに何回分の操作を終えたか
	// FinalCand はギリギリまで考えたときに何個のアメを追加したか
	long long MaximumCycles = (K - u2) / (u2 - u1);
	long long FinalTime = u2 + MaximumCycles * (u2 - u1);
	long long FinalCand = CurrentCand + MaximumCycles * CycleCand;

	// 手順 3: 最後はシミュレーション
	while (FinalTime < K) {
		FinalTime += 1;
		FinalCand += A[FinalCand % N];
	}

	// 出力
	cout << FinalCand << endl;
	return 0;
}
